import requests, os, numpy as np, matplotlib.pyplot as plt, json
S="struct"; os.makedirs(S, exist_ok=True)
targets = {
 "NVJ3_yeast":"Q03983","MDM1_yeast":"Q01846",
 "SNX13_human":"Q9Y5W8","SNX14_human":"Q9Y5W7","SNX19_human":"Q92543","SNX25_human":"Q9H3E2",
 "SEC14_yeast":"P24280","OSH4_yeast":"P35844","PRY1_yeast":"P47032",
 "PGK1_yeast":"P00560","TPI1_yeast":"P00942","SNX3_yeast_Grd19":"P38784",
}
for name,acc in targets.items():
    p=f"{S}/{name}.pdb"
    if os.path.exists(p) and os.path.getsize(p)>10000: continue
    for v in ("v4","v6"):
        r=requests.get(f"https://alphafold.ebi.ac.uk/files/AF-{acc}-F1-model_{v}.pdb", timeout=120)
        if r.status_code==200 and r.text.startswith(("HEADER","ATOM","MODEL","DBREF")):
            open(p,"w").write(r.text); break
print(sorted(os.listdir(S)))

def parse_pdb(path):
    atoms=[]
    for l in open(path):
        if l.startswith("ATOM"):
            el=(l[76:78].strip().upper() or l[12:16].strip()[0])
            atoms.append(dict(name=l[12:16].strip(), resn=l[17:20].strip(), resi=int(l[22:26]),
                              xyz=(float(l[30:38]),float(l[38:46]),float(l[46:54])), b=float(l[60:66]), el=el))
    return atoms

store={k:parse_pdb(f"{S}/{k}.pdb") for k in targets}
PXA={"NVJ3_yeast":(98,239),"MDM1_yeast":(87,271),"SNX13_human":(98,278),"SNX14_human":(130,298),
     "SNX19_human":(97,265),"SNX25_human":(2,157)}

for k,a in store.items():
    ca=[x for x in a if x["name"]=="CA"]; pl=np.array([x["b"] for x in ca])
    print(f"{k:18s} n={len(ca):5d} meanpLDDT={pl.mean():5.1f} frac>70={np.mean(pl>70):.2f}")

fig,axes=plt.subplots(3,2,figsize=(13,9))
for ax,(k,(s,e)) in zip(axes.ravel(),PXA.items()):
    ca=[x for x in store[k] if x["name"]=="CA"]
    r=np.array([x["resi"] for x in ca]); b=np.array([x["b"] for x in ca])
    ax.plot(r,b,lw=0.8,color="#2b5d8a"); ax.axvspan(s,e,color="orange",alpha=0.25,label="Pfam PF02194")
    ax.axhline(70,ls="--",c="grey",lw=0.7); ax.set_ylim(0,100)
    ax.set_title(k,fontsize=10); ax.set_xlabel("residue"); ax.set_ylabel("pLDDT"); ax.legend(fontsize=7)
plt.suptitle("AlphaFold pLDDT, PXA-domain proteins (Pfam PF02194 span shaded)")
plt.tight_layout(); plt.show()
for k,(s,e) in PXA.items():
    ca=[x for x in store[k] if x["name"]=="CA" and s<=x["resi"]<=e]
    print(f"{k:14s} PXA {s}-{e} meanpLDDT={np.mean([x['b'] for x in ca]):.1f}")
